def model(z, v):
    a = [compact(z, j) for j in range(4)]
    w = np.ones(len(z))
    for _ in range(25):
        sw = np.sqrt(w)
        b = np.array([np.linalg.lstsq(t * sw[:, None], v[:, j] * sw, rcond=None)[0] for (j, t) in enumerate(a)])
        r = np.linalg.norm(v - np.column_stack([t @ b[j] for (j, t) in enumerate(a)]), axis=1)
        w = 1 / (1 + (r / max(1e-07, 2 * np.median(r))) ** 2)
    keep = r <= max(1e-06, 8 * np.median(r))
    return (np.array([np.linalg.lstsq(t[keep], v[keep, j], rcond=None)[0] for (j, t) in enumerate(a)]), keep)
